use verus::prelude::*;

verus! {

    /// Given a non-negative size `n`, construct a Vec<i8> of length `n`
    /// where every element is exactly 1.
    ///
    /// Postconditions:
    /// 1. The returned vector has length `n`.
    /// 2. For every index `i < n`, `result@[i] == 1`.
    /// 3. Equivalently, `result@ == Seq::from_elem(1, n)`.
    fn ones(n: usize) -> (result: Vec<i8>)
        ensures
            // The spec‐level sequence of the result is exactly n copies of 1
            result@ == Seq::from_elem(1, n)
    {
        let mut v: Vec<i8> = Vec::new();
        let mut i: usize = 0;

        // Build the vector by pushing 1's one at a time.
        while i < n {
            invariant i <= n;
            invariant v.len() == i;
            invariant v@ == Seq::from_elem(1, i);
            decreases n - i;

            v.push(1);
            i += 1;
        }

        // At this point i == n and v.len() == n and v@ == Seq::from_elem(1, n)
        v
    }
}